    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case Request_Qualification_dispatch_coordination_process_request_qualification_id =>
          val prefix = "Request_Qualification_dispatch_coordination_process_request_qualification_RM_TestSuite"
          val path = testRoot /+ ISZ("factory_dispatch_coordinator","Factory_Dispatch_Coordinator")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package factory_dispatch_coordinator.Factory_Dispatch_Coordinator
                |
                |import org.sireum._
                |import factory_dispatch_coordinator.Factory_Dispatch_Coordinator._
                |
                |class ${suiteName} extends Request_Qualification_dispatch_coordination_process_request_qualification_GumboX_TestHarness_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case Request_Registry_dispatch_coordination_process_request_registry_id =>
