  def getUpdates(bridge_id: art.Art.BridgeId, observationKind: ObservationKind.Type, container: art.DataContent): Map[String, String] = {
    observationKind match {
      case factory_dispatch_coordinator.runtimemonitor.ObservationKind.Finished_Product_Dispatch_Coordinator_System_Instance_dispatch_coordination_process_request_qualification_postInit =>
        var updates: Map[String, String] = Map.empty
        val postContainer = container.asInstanceOf[factory_dispatch_coordinator.Factory_Dispatch_Coordinator.Request_Qualification_dispatch_coordination_process_request_qualification_PostState_Container_PS]
        updates = updates + s"${bridge_id}_Out_arrival_fact" ~> postContainer.api_arrival_fact.string
        return updates
      case factory_dispatch_coordinator.runtimemonitor.ObservationKind.Finished_Product_Dispatch_Coordinator_System_Instance_dispatch_coordination_process_request_registry_postInit =>
